#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int val(char c) {
    switch(c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
    }
    return 0;
}

int romanToInt(const char* s) {
    int total = 0;
    int prev = 0;
    for (int i = 0; s[i]; ++i) {
        int v = val(s[i]);
        if (prev < v) {
            total += v - 2 * prev;
        } else {
            total += v;
        }
        prev = v;
    }
    return total;
}

int main(void) {
    char line[256];
    if (!fgets(line, sizeof(line), stdin)) return 0;
    int len = (int)strlen(line);
    while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) line[--len] = '\0';
    if (len >= 2) {
        char inner[64];
        strncpy(inner, line+1, len-2);
        inner[len-2] = '\0';
        printf("%d\n", romanToInt(inner));
    }
    return 0;
}

